    // ---- module closure (gates 2, 13, 1) ----

    #[test]
    fn every_way_to_pull_a_file_into_a_build_script_is_followed() {
        let (read, exists) = tracked(&[
            (
                "c/build.rs",
                "#[path = \"extra.rs\"]\nmod p;\npub(crate) mod v;\npub(in crate) mod w;\ninclude!(\"inc.rs\");\nmod plain;\n",
            ),
            ("c/extra.rs", "mod deeper;\n"),
            ("c/deeper.rs", ""),
            ("c/v.rs", ""),
            ("c/w/mod.rs", "mod inner;\n"),
            ("c/w/inner.rs", ""),
            ("c/inc.rs", ""),
            ("c/plain.rs", ""),
        ]);
        let (files, errs) = closure(&["c/build.rs".to_owned()], &read, &exists);
        assert!(errs.is_empty(), "{errs:?}");
        for f in [
            "c/build.rs",
            "c/extra.rs",
            "c/deeper.rs",
            "c/v.rs",
            "c/w/mod.rs",
            "c/w/inner.rs",
            "c/inc.rs",
            "c/plain.rs",
        ] {
            assert!(files.contains(f), "{f} missing from {files:?}");
        }
    }

    #[test]
    fn a_non_root_file_resolves_children_under_its_own_stem() {
        let (read, exists) = tracked(&[
            ("c/src/lib.rs", "mod a;\n"),
            ("c/src/a.rs", "mod b;\nmod inline { mod c; }\n"),
            ("c/src/a/b.rs", ""),
            ("c/src/a/inline/c.rs", ""),
        ]);
        let (files, errs) = closure(&["c/src/lib.rs".to_owned()], &read, &exists);
        assert!(errs.is_empty(), "{errs:?}");
        assert!(files.contains("c/src/a/b.rs") && files.contains("c/src/a/inline/c.rs"));
    }

    #[test]
    fn what_cannot_be_resolved_is_refused_rather_than_skipped() {
        for root in [
            "include!(concat!(env!(\"OUT_DIR\"), \"/x.rs\"));",
            "mod missing;",
            "#[cfg_attr(unix, path = \"x.rs\")]\nmod m;",
            "macro_rules! m { ($n:ident) => { mod $n; } }",
            "fn f() { mod hidden; }",
            "#[path = \"../nowhere.rs\"] mod n;",
        ] {
            let (read, exists) = tracked(&[("c/build.rs", root)]);
            let (_, errs) = closure(&["c/build.rs".to_owned()], &read, &exists);
            assert!(!errs.is_empty(), "resolved: {root}");
        }
    }

    #[test]
    fn the_production_closure_follows_paths_and_not_stems() {
        // P1-08-04, D-2660. `manifest` is a crate-root test module AND a
        // production file under `resume/`; the stem rule skipped both.
        let (read, exists) = tracked(&[
            (
                "crates/e/src/lib.rs",
                "#[cfg(test)]\nmod manifest;\nmod resume;\n#[path = \"../stamp.rs\"]\nmod stamp;\n#[cfg(test)]\nmod t { mod deep; }\nmod whole;\n#[cfg(all(test, unix))]\n#[path = \"../tests/support/mod.rs\"]\nmod support;\n#[cfg(all(test))]\nmod mutated;\n",
            ),
            ("crates/e/src/manifest.rs", "fn test_only() {}\n"),
            ("crates/e/src/resume.rs", "mod manifest;\n"),
            (
                "crates/e/src/resume/manifest.rs",
                "pub fn prod() { v.sort(); }\n",
            ),
            (
                "crates/e/stamp.rs",
                "pub fn stamp() { eprintln!(\"x\"); }\n",
            ),
            ("crates/e/src/t/deep.rs", "fn d() {}\n"),
            ("crates/e/src/whole.rs", "#![cfg(test)]\nfn w() {}\n"),
            ("crates/e/tests/support/mod.rs", "fn s() {}\n"),
            ("crates/e/src/mutated.rs", "fn m() {}\n"),
        ]);
        let (files, errs) = prod_closure(&["crates/e/src/lib.rs".to_owned()], &read, &exists);
        assert!(errs.is_empty(), "{errs:?}");
        let got: Vec<&str> = files.iter().map(String::as_str).collect();
        assert_eq!(
            got,
            [
                "crates/e/src/lib.rs",
                "crates/e/src/resume.rs",
                "crates/e/src/resume/manifest.rs",
                "crates/e/stamp.rs",
            ]
        );
        assert!(is_prod_root("crates/e/src/lib.rs"));
        assert!(is_prod_root("crates/e/src/bin/x.rs"));
        assert!(!is_prod_root("crates/e/tests/x.rs"));
        assert!(!is_prod_root("crates/e/build.rs"));
    }

    #[test]
    fn a_cycle_terminates() {
        let (read, exists) = tracked(&[("c/lib.rs", "#[path = \"lib.rs\"] mod me;\n")]);
        let (files, errs) = closure(&["c/lib.rs".to_owned()], &read, &exists);
        assert!(errs.is_empty());
        assert_eq!(files.len(), 1);
    }

    #[test]
    fn a_file_is_named_by_the_module_it_is_mounted_as() {
        let (read, exists) = tracked(&[
            (
                "c/src/lib.rs",
                "mod server;\nmod a { #[path = \"../t.rs\"] mod tests; }\n",
            ),
            (
                "c/src/server.rs",
                "#[path = \"wire.rs\"]\nmod store_wire;\n",
            ),
            ("c/src/wire.rs", "mod tests {}\n"),
            ("c/src/t.rs", ""),
            ("c/tests/it.rs", "mod helper;\n"),
            ("c/tests/helper.rs", ""),
            ("c/src/me.rs", "#[path = \"me.rs\"] mod again;\n"),
        ]);
        let roots = [
            ("c/src/lib.rs".to_owned(), Vec::new()),
            ("c/tests/it.rs".to_owned(), vec!["it".to_owned()]),
            ("c/src/me.rs".to_owned(), Vec::new()),
        ];
        let (mounted, errs) = module_paths(&roots, &read, &exists);
        assert!(errs.is_empty(), "{errs:?}");
        let has = |f: &str, m: &str| mounted.contains(&(f.to_owned(), m.to_owned()));
        assert!(has("c/src/lib.rs", ""));
        assert!(has("c/src/wire.rs", "server::store_wire"));
        assert!(!mounted.iter().any(|(f, _)| f == "c/src/store_wire.rs"));
        assert!(has("c/src/t.rs", "a::tests"));
        assert!(has("c/tests/helper.rs", "it::helper"));
        // A file that mounts itself is named once and the walk ends.
        assert_eq!(
            mounted.iter().filter(|(f, _)| f == "c/src/me.rs").count(),
            1
        );
    }

