    // ---- the workflow (gates 13, 14, 0) ----

    const WF: &str = "jobs:\n  build:\n    runs-on: x\n    steps:\n      - name: Gate 3\n        run: |\n          cargo deny check\n  ci-ok:\n    needs: [build]\n    steps:\n      - run: true\n";

    #[test]
    fn an_unconditional_step_is_present() {
        assert_eq!(step_runs(WF, "cargo deny check"), Ok(1));
    }

    #[test]
    fn every_way_to_switch_a_step_off_is_refused() {
        for (from, to) in [
            (
                "      - name: Gate 3\n",
                "      - name: Gate 3\n        continue-on-error: true\n",
            ),
            (
                "      - name: Gate 3\n",
                "      - name: Gate 3\n        if: false && true\n",
            ),
            (
                "      - name: Gate 3\n",
                "      - name: Gate 3\n        if: github.run_attempt == 0\n",
            ),
            (
                "      - name: Gate 3\n",
                "      - name: Gate 3\n        if: steps.probe.outputs.has_crates == 'false'\n",
            ),
            (
                "      - name: Gate 3\n",
                "      - continue-on-error: true\n        name: Gate 3\n",
            ),
            (
                "    runs-on: x\n",
                "    runs-on: x\n    continue-on-error: true\n",
            ),
            ("    runs-on: x\n", "    runs-on: x\n    if: ${{ false }}\n"),
            ("    needs: [build]\n", "    needs: [other]\n"),
            (
                "          cargo deny check\n",
                "          echo cargo deny check\n",
            ),
        ] {
            let wf = WF.replacen(from, to, 1);
            assert!(step_runs(&wf, "cargo deny check").is_err(), "passed: {to}");
        }
    }

